    explanation: "The 'Five Whys' method (originating from Toyota Production System and adapted by healthcare safety) repeatedly asks 'Why did that happen?' to move beyond the superficial, proximal human error (e.g., 'the nurse didn't check the blood pressure') to the latent organizational failure (e.g., equipment broken -> no spare cuffs -> no maintenance contract -> procurement cost-cutting without clinical sign-off). Five iterations typically reveal the core systemic vulnerability.",
