    correctAnswer: "A",
    explanation: "In Reason's Swiss Cheese Model, 'active failures' are the unsafe acts committed by people who are in direct contact with the patient (frontline staff), such as momentary slips, lapses, or rule violations (e.g., leaving a door unlocked during a distraction). 'Latent conditions' are the hidden pathogens residing within the organizational system for long periods (e.g., defective maintenance, understaffing, poor training, flawed physical architecture) that align to create an accident trajectory.",
