    difficulty: "Intermediate",
    questionText: "In Sidney Dekker's and the NHS's 'Just Culture' framework, what algorithm is utilized when assessing an individual clinician's actions following a serious clinical incident to determine whether the behavior was an honest human error, at-risk behavior, or reckless misconduct?",
