    explanation: "The 'Substitution Test' (Reason, Dekker, NHS Just Culture Guide) is a central component of fair safety cultures. It asks: 'Given the same circumstances, environment, fatigue, and systemic pressures, would three other peers with comparable skills and experience have done the same thing?' If yes, the problem is systemic, and blaming the individual is completely unjustified. Reckless behavior (deliberate conscious disregard of unjustifiable risk) is distinguished from blameless human error.",
