    correctAnswer: "A",
    explanation: "Recording vital signs in a stable patient is a standardized technical task suitable for delegation to trained, competent healthcare support workers, provided parameters for reporting abnormalities are clearly established. Conversely, complex clinical triage, legal detention admissions, comprehensive risk formulation, authorizing Section 17 leave, and parenteral/titrated medication administration require registered professional clinical judgment, diagnostic reasoning, and legal authority that cannot be delegated to unregistered staff.",
