    topic: "Delegation and supervision",
    difficulty: "Intermediate",
    questionText: "Under the NMC Standards for Student Supervision and Assessment (SSSA, 2018), what is the key distinction between the role of a 'Practice Supervisor' and that of a 'Practice Assessor'?",
