    id: "MHN-Q1149",
    module: "12. Leadership and Professional Practice",
    topic: "Delegation and supervision",
    difficulty: "Intermediate",
    questionText: "A registered mental health nurse is delegating 1:1 enhanced engagement observations of an acutely suicidal patient to a newly recruited agency healthcare assistant. Which communication model provides the most structured and unambiguous framework for delegating safety-critical tasks?",
