    topic: "Multidisciplinary team (MDT) functioning",
    difficulty: "Intermediate",
    questionText: "Bruce Tuckman's model of team development outlines five stages: Forming, Storming, Norming, Performing, and Adjourning. A newly established Crisis Resolution Home Treatment (CRHT) team is experiencing interpersonal friction, ideological clashes between medical and nursing staff, and role ambiguity. In which Tuckman stage is this team operating, and what leadership response is needed?",
